<?php namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Log;
class AuthController extends Controller {public function showLogin(){return view('auth.login');} public function login(Request $r){Log::info('AuthController@login called with email: '.$r->input('email'));$c=$r->validate(['email'=>'required|email','password'=>'required']);$user=\App\Models\User::where('email',$c['email'])->first();if(!$user){Log::info('User not found: '.$c['email']);return back()->withErrors(['email'=>'User not found.'])->withInput();}Log::info('User found: '.$c['email'].', Active: '.($user->active ? 'yes' : 'no'));if(!$user->active){return back()->withErrors(['email'=>'Account is inactive.'])->withInput();}$check=\Hash::check($c['password'],$user->password);Log::info('Password check for '.$c['email'].': '.($check ? 'success' : 'failed'));if($check){Auth::login($user,$r->boolean('remember'));$r->session()->regenerate();return redirect()->intended('/dashboard');}return back()->withErrors(['email'=>'Invalid credentials.'])->withInput();}public function logout(Request $r){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return redirect()->route('login');}}
